    public string Description { get; set; } = string.Empty;
    public List<string> Ingredients { get; set; } = [];
    public List<string> Steps { get; set; } = [];
    public double AverageRating { get; set; }
    public int RatingCount { get; set; }
}

public class RecipeSubmission
{
    public string Title { get; set; } = string.Empty;
    public string Category { get; set; } = string.Empty;
    public string Ingredients { get; set; } = string.Empty;
    public string Steps { get; set; } = string.Empty;
}

using RecipeShare.Models;

namespace RecipeShare.Services;

public class RecipeService
{
    private readonly List<Recipe> _recipes =
    [
        new()
        {
            Id = 1, Title = "Classic Margherita Pizza", Category = "Italian",
            Description = "A simple yet delicious pizza with fresh mozzarella and basil.",
            Ingredients = ["Pizza dough", "San Marzano tomatoes", "Fresh mozzarella", "Fresh basil", "Olive oil", "Salt"],
            Steps = ["Preheat oven to 475°F.", "Roll out dough on a floured surface.", "Spread crushed tomatoes evenly.", "Tear mozzarella and distribute.", "Bake for 10-12 minutes.", "Top with fresh basil and drizzle olive oil."],
            AverageRating = 4.5, RatingCount = 12
        },
        new()
        {
            Id = 2, Title = "Chicken Tikka Masala", Category = "Indian",
            Description = "Tender chicken in a creamy spiced tomato sauce.",
            Ingredients = ["Chicken breast", "Yogurt", "Garam masala", "Tomato puree", "Heavy cream", "Onion", "Garlic", "Ginger"],
            Steps = ["Marinate chicken in yogurt and spices for 2 hours.", "Grill or pan-fry chicken until charred.", "Sauté onion, garlic, and ginger.", "Add tomato puree and simmer.", "Stir in cream and spices.", "Add chicken and simmer 10 minutes."],
            AverageRating = 4.8, RatingCount = 24
        },
        new()
        {
            Id = 3, Title = "Beef Tacos", Category = "Mexican",
            Description = "Seasoned ground beef in crispy taco shells with fresh toppings.",
            Ingredients = ["Ground beef", "Taco seasoning", "Taco shells", "Lettuce", "Tomato", "Cheddar cheese", "Sour cream"],
            Steps = ["Brown ground beef in a skillet.", "Add taco seasoning and water, simmer 5 minutes.", "Warm taco shells.", "Fill shells with beef.", "Top with lettuce, tomato, cheese, and sour cream."],
            AverageRating = 4.2, RatingCount = 8
        },
        new()
        {
            Id = 4, Title = "Spaghetti Carbonara", Category = "Italian",
            Description = "A Roman classic with eggs, pecorino, and guanciale.",
            Ingredients = ["Spaghetti", "Guanciale", "Egg yolks", "Pecorino Romano", "Black pepper"],
            Steps = ["Cook spaghetti in salted water.", "Crisp guanciale in a pan.", "Whisk egg yolks with grated pecorino and pepper.", "Toss hot pasta with guanciale.", "Remove from heat, stir in egg mixture.", "Serve immediately with extra pecorino."],
            AverageRating = 4.7, RatingCount = 18
        },
        new()
        {
            Id = 5, Title = "Pad Thai", Category = "Thai",
            Description = "Stir-fried rice noodles with shrimp, peanuts, and tamarind sauce.",
            Ingredients = ["Rice noodles", "Shrimp", "Eggs", "Bean sprouts", "Peanuts", "Tamarind paste", "Fish sauce", "Lime"],
            Steps = ["Soak rice noodles in warm water.", "Stir-fry shrimp until pink, set aside.", "Scramble eggs in the wok.", "Add noodles, tamarind, and fish sauce.", "Toss with shrimp and bean sprouts.", "Serve with crushed peanuts and lime wedges."],
            AverageRating = 4.4, RatingCount = 15
        },
        new()
        {
            Id = 6, Title = "Guacamole", Category = "Mexican",
            Description = "Fresh and zesty avocado dip perfect for chips or tacos.",
            Ingredients = ["Avocados", "Lime juice", "Red onion", "Cilantro", "Jalapeño", "Salt"],
            Steps = ["Halve and pit avocados.", "Mash to desired consistency.", "Mix in lime juice, diced onion, cilantro, and jalapeño.", "Season with salt.", "Serve immediately."],
            AverageRating = 4.6, RatingCount = 20
        }
    ];

    public List<string> GetCategories() =>
        _recipes.Select(r => r.Category).Distinct().OrderBy(c => c).ToList();

    public List<Recipe> GetByCategory(string category) =>
        _recipes.Where(r => r.Category.Equals(category, StringComparison.OrdinalIgnoreCase)).ToList();

    public Recipe? GetById(int id) =>
        _recipes.FirstOrDefault(r => r.Id == id);

    public void AddRating(int recipeId, int stars)
    {
        var recipe = GetById(recipeId);
        if (recipe is null || stars < 1 || stars > 5) return;

        var totalStars = recipe.AverageRating * recipe.RatingCount + stars;
        recipe.RatingCount++;
        recipe.AverageRating = Math.Round(totalStars / recipe.RatingCount, 1);
    }

    public void AddRecipe(RecipeSubmission submission)
    {
        var newId = _recipes.Max(r => r.Id) + 1;
        _recipes.Add(new Recipe
        {
            Id = newId,
            Title = submission.Title,
            Category = submission.Category,
            Description = $"A community-submitted recipe for {submission.Title}.",
            Ingredients = submission.Ingredients.Split('\n', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries).ToList(),
            Steps = submission.Steps.Split('\n', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries).ToList(),
            AverageRating = 0,
            RatingCount = 0
        });
    }
}

